using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CommunityEconomyTests
{
    static WorldSession Start(string person="person:nobunaga",ulong seed=42)=>new(NewGameWorld.Create(NewGameWorld.Scenario(),[],person,seed,economyPolicy:CommunityEconomy.Policy));
    static CommunityAccounts A(WorldSession s,string site="site:castle")=>s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site.Value==site);
    static CommandResult Act(WorldSession s,EconomyAction action,long n,string id="request:community",string site="site:castle")=>s.ManageCommunity(new(new(id),new(site),action,n),s.PlayerControl,s.Revision);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long before=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>before);}}
    static long Day(WorldSession s,int year,int month,int day)=>(new DateOnly(year,month,day).DayNumber-DateOnly.Parse(s.DiagnosticSnapshot().EpochDate).DayNumber)*86400L;
    [Fact]public void ThreeIndependentLedgersAndSeparatePhysicalStocks(){var s=Start();Assert.Equal(3,s.DiagnosticSnapshot().Communities!.Accounts.Length);Assert.Null(s.DiagnosticSnapshot().Economy);var before=A(s,"site:kofu");var lots=ContractJson.Write(s.DiagnosticSnapshot().ResourceLots);Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,100).Code);Assert.Equal(before,A(s,"site:kofu"));Assert.Equal(9900+200,A(s).VillageRice);Assert.Equal(2900,A(s).HouseRice);Assert.Equal(lots,ContractJson.Write(s.DiagnosticSnapshot().ResourceLots));Assert.Empty(s.DiagnosticSnapshot().Transfers);}
    [Theory][InlineData("person:nobunaga","site:castle")][InlineData("person:shingen","site:kofu")][InlineData("person:ujiyasu","site:odawara")]
    public void EachHeadCanManageOnlyTheirLocalVillage(string person,string site){var s=Start(person);Assert.NotNull(s.CommunityEconomyView());Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,1,site:site).Code);var other=CommunityEconomy.Sites.First(x=>x.Value!=site);Assert.Equal(ResultCode.NotAvailable,Act(s,EconomyAction.RelieveVillage,1,"request:foreign",other.Value).Code);}
    [Fact]public void LaborReservedThenReleasedOnlyAtActualWorkCompletion(){var s=Start();Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.ImproveWater,200).Code);Assert.Equal(20,A(s).Reserved);Assert.Equal(2800,A(s).HouseRice);Advance(s,CommunityEconomy.WorkSeconds-1);Assert.Equal(100,A(s).Water);Advance(s,CommunityEconomy.WorkSeconds);Assert.Equal(110,A(s).Water);Assert.Equal(0,A(s).Reserved);}
    [Theory][InlineData(EconomyAction.RelieveVillage,3001)][InlineData(EconomyAction.RelieveVillage,0)][InlineData(EconomyAction.CollectLevy,1)][InlineData(EconomyAction.ImproveWater,199)]
    public void InvalidActionsAreAtomic(EconomyAction action,long n){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,action,n).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void IdempotencyAndStaleViewCannotSpendTwice(){var s=Start();long shown=s.Revision;Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,10).Code);Assert.Equal(ResultCode.AlreadyAccepted,Act(s,EconomyAction.RelieveVillage,10).Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,EconomyAction.RelieveVillage,11).Code);Assert.Equal(ResultCode.StateChanged,s.ManageCommunity(new(new("request:stale"),new("site:castle"),EconomyAction.RelieveVillage,1),s.PlayerControl,shown).Code);Assert.Equal(2990,A(s).HouseRice);}
    [Fact]public void MonthlyFoodAndHarvestPreserveMassAndAssessBeforeCollection(){var s=Start();int y=DateOnly.Parse(s.DiagnosticSnapshot().EpochDate).Year;Advance(s,Day(s,y,2,1));Assert.Equal(1000,A(s).Consumed);Assert.Equal("未観測",A(s).Climate);Advance(s,Day(s,y,10,1));var a=A(s);Assert.True(a.Harvested>0);Assert.Equal(a.Harvested*3/10,a.Assessed);Assert.Equal(0,a.Collected);Assert.Equal(13000+a.Harvested,a.VillageRice+a.HouseRice+a.Consumed+a.WorksSpent);Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.CollectLevy,1).Code);Assert.Equal(3001,A(s).HouseRice);}
    [Fact]public void SameSeedAndChunkingPreserveObservedAccounts(){var a=Start();var b=Start();int y=DateOnly.Parse(a.DiagnosticSnapshot().EpochDate).Year;long end=Day(a,y,10,1);Advance(a,end);Advance(b,Day(b,y,9,1));Advance(b,end);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().Communities),ContractJson.Write(b.DiagnosticSnapshot().Communities));}
    [Fact]public void TamperedAccountsAndOrdersAreRejected(){var s=Start();Act(s,EconomyAction.RelieveVillage,10);var w=s.DiagnosticSnapshot();w.Communities=w.Communities! with{Accounts=[..w.Communities.Accounts.Select(a=>a with{HouseRice=999})]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Communities=w.Communities! with{Orders=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ActualGenerationRecoveryDuringWorkHasIdenticalFuture(){var a=Start();Act(a,EconomyAction.ImproveWater,200);Advance(a,123);a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"community-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"work",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("work"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));int y=DateOnly.Parse(w.EpochDate).Year;Advance(a,Day(a,y,10,1));Advance(b,Day(b,y,10,1));Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}
    [Fact]public void OldNullAndSingleVillagePoliciesStayIndependent(){foreach(var policy in new string?[]{null,RegionalEconomy.Policy}){var s=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(),[],"person:nobunaga",economyPolicy:policy));var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Null(s.DiagnosticSnapshot().Communities);Assert.DoesNotContain("Communities",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));var w=s.DiagnosticSnapshot();w.Communities=Start().DiagnosticSnapshot().Communities;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}}

    [Fact]public void ReservedHarvestLaborReducesActualYieldUntilWorkFinishes(){var a=Start(seed:285);var b=Start(seed:285);Advance(a,Day(a,1560,9,28));Assert.Equal(ResultCode.Accepted,Act(a,EconomyAction.ImproveWater,200).Code);Advance(a,Day(a,1560,10,1));Advance(b,Day(b,1560,10,1));Assert.Equal(8000,A(a).Harvested);Assert.Equal(10000,A(b).Harvested);Assert.Equal(20,A(a).Reserved);Advance(a,Day(a,1560,10,5));Assert.Equal(0,A(a).Reserved);Assert.Equal(110,A(a).Water);}
    static WorldSession PausedFoodWork(){var s=Start(seed:285);Advance(s,Day(s,1560,10,1));Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.CollectLevy,3000,"request:levy").Code);Advance(s,Day(s,1561,6,30));Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.ImproveWater,200,"request:water").Code);Advance(s,Day(s,1561,7,1));Assert.Equal(1000,A(s).Hunger);Assert.Null(A(s).WorkDue);Assert.Equal(6*86400,A(s).WorkRemaining);return s;}
    [Fact]public void ActualShortagePausesLaborReliefConsumesHouseStockThenResumesRemainingWork(){var s=PausedFoodWork();long house=A(s).HouseRice;var notice=s.DiagnosticSnapshot().Communities!.Notices.Single(n=>n.Site.Value=="site:castle");Assert.Equal(1000,notice.Need);Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,1000,"request:aid").Code);Assert.Equal(house-1000,A(s).HouseRice);Assert.Equal(0,A(s).Hunger);Assert.Equal(0,A(s).VillageRice);Assert.Equal(s.Seconds+6*86400,A(s).WorkDue);Assert.Equal(notice,s.DiagnosticSnapshot().Communities!.Notices.Single(n=>n.Site==notice.Site));Advance(s,s.Seconds+6*86400);Assert.Equal(110,A(s).Water);Assert.Equal(0,A(s).Reserved);}
    [Fact]public void ActualGenerationRecoveryOfPausedAndResumedWorkPreservesFutureAndFrozenReport(){var a=PausedFoodWork();a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"community-famine-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"paused",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("paused"),host.Current,host.Current.Revision));var b=host.Current;Export(a,b,"community-paused");foreach(var s in new[]{a,b})Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,1000,"request:aid").Code);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));a.SetPaused(true);Assert.True(store.Save(a,"resumed",w.WorldId).Published);var h=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,h.CommitLoad(store.Prepare("resumed"),h.Current,h.Current.Revision));Export(a,h.Current,"community-resumed");b=h.Current;long end=a.Seconds+7*86400;Advance(a,end);Advance(b,end);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}
    [Fact]public void UnknownForeignAccountsAndWrongActorCannotBeReadOrSpent(){var s=Start();Assert.Null(CommunityEconomy.View(s.DiagnosticSnapshot(),new("person:shingen")));Assert.Equal(ResultCode.NotAvailable,s.ManageCommunity(new(new("request:wrong"),new("site:castle"),EconomyAction.RelieveVillage,1),new("person:shingen"),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,EconomyAction.RelieveVillage,1,site:"site:kofu").Code);Assert.Empty(s.DiagnosticSnapshot().Communities!.Notices);}
    [Fact]public void EconomicInputCannotBecomeCommonTravelIntent(){var s=Start();Assert.Equal(ResultCode.Accepted,Act(s,EconomyAction.RelieveVillage,1).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:community","sakai"),s.Revision).Code);}
    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrEmpty(dir))return;Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,name+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,name+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}
}
